-- JEE WAR ROOM database dump
-- generated 2026-09-21T09:16:01.530215+00:00
PRAGMA foreign_keys=OFF;
BEGIN;

DROP TABLE IF EXISTS activities;
CREATE TABLE activities (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, type TEXT NOT NULL, custom_key TEXT, subject TEXT, chapter TEXT, amount INTEGER DEFAULT 0, duration INTEGER DEFAULT 0, extra TEXT, note TEXT, day TEXT NOT NULL, created_at TEXT NOT NULL);
DROP TABLE IF EXISTS announcements;
CREATE TABLE announcements (id INTEGER PRIMARY KEY, body TEXT NOT NULL, created_at TEXT NOT NULL);
DROP TABLE IF EXISTS app_settings;
CREATE TABLE app_settings (id INTEGER PRIMARY KEY CHECK (id = 1), json TEXT NOT NULL DEFAULT '{}');
DROP TABLE IF EXISTS chapters;
CREATE TABLE chapters (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, subject TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'not_started', hidden INTEGER NOT NULL DEFAULT 0, sort INTEGER NOT NULL DEFAULT 0, custom INTEGER NOT NULL DEFAULT 0, lectures_total INTEGER NOT NULL DEFAULT 0, lectures_done INTEGER NOT NULL DEFAULT 0);
DROP TABLE IF EXISTS errors;
CREATE TABLE errors (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, subject TEXT, chapter TEXT, etype TEXT, qno TEXT, note TEXT, day TEXT NOT NULL, created_at TEXT NOT NULL);
DROP TABLE IF EXISTS friendships;
CREATE TABLE friendships (user_id INTEGER NOT NULL, friend_id INTEGER NOT NULL, created_at TEXT, PRIMARY KEY (user_id, friend_id));
DROP TABLE IF EXISTS messages;
CREATE TABLE messages (id INTEGER PRIMARY KEY, sender INTEGER NOT NULL, recipient INTEGER NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT, hidden TEXT NOT NULL DEFAULT '');
DROP TABLE IF EXISTS mocks;
CREATE TABLE mocks (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, test_type TEXT, total INTEGER DEFAULT 300, score REAL, phys REAL, chem REAL, math REAL, attempted INTEGER, correct INTEGER, incorrect INTEGER, day TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
DROP TABLE IF EXISTS nonces;
CREATE TABLE nonces (nonce TEXT PRIMARY KEY, user_id INTEGER, created_at REAL, result TEXT);
DROP TABLE IF EXISTS reports;
CREATE TABLE reports(
      id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, body TEXT NOT NULL,
      created_at TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0);
DROP TABLE IF EXISTS sessions;
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created_at TEXT);
DROP TABLE IF EXISTS settings;
CREATE TABLE settings (user_id INTEGER PRIMARY KEY, json TEXT NOT NULL);
DROP TABLE IF EXISTS snapshots;
CREATE TABLE snapshots (user_id INTEGER NOT NULL, day TEXT NOT NULL, score REAL NOT NULL, air INTEGER NOT NULL, PRIMARY KEY (user_id, day));
DROP TABLE IF EXISTS targets;
CREATE TABLE targets (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, day TEXT NOT NULL, kind TEXT, subject TEXT, chapter TEXT, title TEXT NOT NULL, amount INTEGER, duration INTEGER, status TEXT NOT NULL DEFAULT 'open', created_at TEXT, completed_at TEXT);
DROP TABLE IF EXISTS timers;
CREATE TABLE timers (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, subject TEXT, chapter TEXT, started REAL NOT NULL, running INTEGER, ended_at TEXT, logged INTEGER DEFAULT 0);
DROP TABLE IF EXISTS users;
CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, pass_hash TEXT NOT NULL, salt TEXT NOT NULL, code TEXT UNIQUE NOT NULL, partner_id INTEGER, exam_date TEXT, avatar_color TEXT, created_at TEXT, role TEXT NOT NULL DEFAULT 'user');
DROP TABLE IF EXISTS xp_events;
CREATE TABLE xp_events (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, amount INTEGER NOT NULL, reason TEXT, ref_type TEXT, ref_id TEXT, day TEXT NOT NULL, created_at TEXT NOT NULL);
DROP INDEX IF EXISTS ix_act_day;
CREATE INDEX ix_act_day ON activities (user_id, day);
DROP INDEX IF EXISTS ix_err_day;
CREATE INDEX ix_err_day ON errors (user_id, day);
DROP INDEX IF EXISTS ix_mock_day;
CREATE INDEX ix_mock_day ON mocks (user_id, day);
DROP INDEX IF EXISTS ix_msg_pair;
CREATE INDEX ix_msg_pair ON messages (recipient, sender, id);
DROP INDEX IF EXISTS ix_t_day;
CREATE INDEX ix_t_day ON targets (user_id, day);

